SELECT  FROM notification_log
WHERE borrow_no = #{borrowNo} AND event_type = #{eventType} AND channel = #{channel}
LIMIT 1

SELECT  FROM notification_log
WHERE status = 'PENDING' AND channel = 'EMAIL' AND created_at < #{before}
ORDER BY id ASC

SELECT  FROM notification_log

    AND status = #{status}
    AND channel = #{channel}
    AND event_type = #{eventType}
    AND DATE(created_at) >= #{startDate}
    AND DATE(created_at) <= #{endDate}

ORDER BY created_at DESC

